-- V45: business partners and procurement foundation
create table if not exists public.a3_business_partners(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id),company_id text not null,partner_type text not null check(partner_type in ('CUSTOMER','SUPPLIER','BOTH')),code text not null,name text not null,email text,active boolean not null default true,unique(owner_id,company_id,code));
create table if not exists public.a3_commercial_documents(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id),company_id text not null,document_type text not null,document_no text not null,partner_id uuid references public.a3_business_partners(id),document_date date not null,status text not null default 'DRAFT',total numeric(18,2) not null default 0,unique(owner_id,company_id,document_type,document_no));
alter table public.a3_business_partners enable row level security; alter table public.a3_commercial_documents enable row level security;
insert into public.a3_schema_migrations(version,name) values(45,'crm suppliers and procurement') on conflict(version) do update set name=excluded.name, applied_at=now();
